import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;

    static int powmod(int a, int x) {
        long res = 1;
        long base = a;
        while (x > 0) {
            if ((x & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            x >>= 1;
        }
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        int va = sc.nextInt();
        int vb = sc.nextInt();

        int den = powmod(va + vb, MOD - 2);
        int pa = (int) (va * 1L * den % MOD);
        int pb = (int) (vb * 1L * den % MOD);
        int one_b = (int) (pa * 1L * powmod(pb, MOD - 2) % MOD);

        int[][] dp = new int[k + 1][k + 2];

        for (int i = k - 1; i >= 0; i--) {
            for (int j = k; j >= 1; j--) {
                if (i + j >= k) {
                    dp[i][j] = (i + j + one_b) % MOD;
                } else {
                    dp[i][j] = (int) ((pa * 1L * dp[i][j + 1] + pb * 1L * dp[i + j][j]) % MOD);
                }
            }
        }

        System.out.println(dp[0][1]);
    }
}

